// Presentation and progress are derived from authored data; they never fill a project implicitly.
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const button=(action,text,ico='',cls='btn',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${ico?icon(ico):''}${text}</button>`;
export const IDEA_SEEDS=[
 {label:'久别重逢',text:'分别多年后，她在即将关门的咖啡馆听见了那个熟悉的声音。'},
 {label:'雨夜悬疑',text:'雨停之前，她必须决定，要不要打开这封没有署名的信。'},
 {label:'日常微光',text:'清晨的早餐铺前，一个陌生人记住了她每天的习惯。'}
];
export function hasCreativeContent(p){return !!(p.logline?.trim()||p.characters?.length||p.scenes?.length||p.props?.length||p.references?.length||p.shots?.some(s=>s.action?.trim()||s.dialogue?.trim()||s.audio?.trim()||s.notes?.trim()||s.emotion||s.micro?.length||Object.keys(s.camera||{}).length||s.segments?.some(x=>x.action?.trim()))||['look','medium','genre','color','custom'].some(k=>p.style?.[k])||p.style?.texture?.length||['framing','move','lens','angle','focus','composition','rotation','zoom'].some(k=>p.camera?.[k])||p.specsChosen||p.negativePrompts?.length||Object.entries(p.commerce||{}).some(([k,v])=>!['output','beats'].includes(k)&&!!v)||p.commerce?.beats?.some(b=>b.action?.trim()||b.voice?.trim()));}
export function workflowSteps(p){return [
 {id:'characters',label:'人物',verb:'设定人物',done:!!p.characters?.length,help:'谁是故事的主角？'},
 {id:'style',label:'质感',verb:'选择质感',done:!!(p.style?.look||p.style?.medium||p.style?.custom),help:'画面应该是什么感觉？'},
 {id:'scenes',label:'场景',verb:'搭建场景',done:!!p.scenes?.length,help:'故事在哪里发生？'},
 {id:'storyboard',label:'分镜',verb:'编排分镜',done:!!p.shots?.some(s=>s.action?.trim()||s.segments?.some(x=>x.action?.trim())),help:'每几秒，发生什么？'}
];}
export function suggestedView(p){if(p.mode==='commerce')return 'commerce';return workflowSteps(p).find(s=>!s.done)?.id||'storyboard';}
export function workflowMarkup(p,view){if(p.mode==='commerce'||view==='start')return '';const steps=workflowSteps(p);return `<nav class="workflow-rail" aria-label="创作步骤">${steps.map((s,i)=>`<button type="button" data-action="navigate" data-view="${s.id}" class="workflow-step ${s.id===view?'current':''} ${s.done?'done':''}" ${s.id===view?'aria-current="step"':''}><span>${s.done?icon('check'):String(i+1).padStart(2,'0')}</span><strong>${s.label}</strong><small>${s.done?'已设定':s.help}</small></button>`).join('')}</nav>`;}
export function nextStepMarkup(p,view,commerceGroup='product'){if(view==='start')return '';if(p.mode==='commerce'){if(view!=='commerce')return '';const next=commerceGroup==='product'?['visual','展示与构图','把商品放进一个合适的画面']:commerceGroup==='visual'&&p.commerce?.output!=='image'?['timeline','广告分段','接下来，安排每几秒展示什么']:null;return `<div class="workspace-next"><span>${icon('layers')}<span>围绕你的真实商品<small>${next?next[2]:'你的商品设定已汇入右侧提示词'}</small></span></span>${next?button('commerce-group','下一步 · '+next[1],'arrow','btn primary small',`data-value="${next[0]}"`):button('show-final-prompt','查看并复制提示词','arrow','btn primary small')}</div>`;}const steps=workflowSteps(p),at=steps.findIndex(s=>s.id===view),next=at>=0&&at<3?steps[at+1]:null;return `<div class="workspace-next"><span>${icon('spark')}<span>${at>=0&&at<3?'细节可以稍后再补':'让这个故事，再向前一步'}<small>${next?next.help:'选好的内容已经汇入右侧提示词'}</small></span></span><div>${next?button('navigate','下一步 · '+next.verb,'arrow','btn primary small',`data-view="${next.id}"`):view==='storyboard'?button('show-final-prompt','查看并复制提示词','arrow','btn primary small'):button('navigate','回到分镜','arrow','btn subtle small','data-view="storyboard"')}</div></div>`;}
export function homeMarkup(p,{hasDraft=false,art=()=>''}={}){
 const recent=hasDraft?`<div class="home-recent"><div class="recent-icon">${icon(p.mode==='commerce'?'layers':'film')}</div><div><small>继续上次的灵感</small><strong>${esc(p.title)}</strong><span>${p.mode==='commerce'?'商品创作':`${p.shots.length} 个镜头`} · 保存在此浏览器</span></div>${button('enter-studio','继续编辑','arrow','btn subtle small')}${button('projects','全部项目','','text-btn')}</div>`:'';
 return `<div class="creative-home" id="creative-home"><header class="home-nav"><button class="home-logo" data-action="home" aria-label="镜序首页"><span class="brand-mark">${icon('film')}</span><span><strong>镜序<span class="brand-dot">.</span></strong><small>AI DIRECTOR STUDIO</small></span></button><nav aria-label="首页导航"><button class="active" data-action="home-scroll" data-target="home-hero">创作首页</button><button data-action="templates">灵感模板</button><button data-action="projects">我的项目</button><span class="home-nav-unavailable">作品灵感馆 <small>即将开放</small></span></nav>${button('enter-studio','进入工作台','arrow','btn home-enter')}</header>
 <main class="home-main"><section class="home-hero" id="home-hero"><img src="./assets/creative-still.jpg" alt="原创电影氛围概念图：雨窗前，一位手持信纸的女性望向远处灯光" fetchpriority="high" width="1536" height="1024"><div class="hero-shade"></div><div class="hero-text"><div class="home-eyebrow"><span></span> 灵感，在此开场 <b>MAKE YOUR FIRST SCENE</b></div><h1>脑海里的那一幕，<br>从这里<span>开始。</span></h1><p>不必先懂所有参数。<br>选人物、定氛围，写下几秒钟的故事。<br>镜序把它们整理成你的镜头提示词。</p><div class="hero-cta">${button('enter-studio','进入工作台','arrow','btn primary')}${button('templates','从模板找灵感','layers','btn hero-secondary')}</div><div class="hero-smallprint"><span>${icon('check')}从零开始也没关系</span><span>${icon('lock')}草稿自动保存在本地</span></div></div><div class="hero-frame-note"><span>SCENE 01</span><strong>一声呼唤之后。</strong><small>原创氛围概念图 · AI生成</small></div><div class="hero-frame-corner"></div><div class="hero-bottom"><span>YOUR IDEA. YOUR FRAME.</span><span>想法 <i>→</i> 人物与场景 <i>→</i> 分镜 <i>→</i> 提示词</span></div></section>
 ${recent}<section class="home-paths" id="home-paths"><div class="home-section-heading"><div><div class="home-eyebrow">CHOOSE YOUR START</div><h2>有个念头，就能开始。</h2></div><p>选一个最像你现在状态的入口。</p></div><div class="creation-paths"><button data-action="new-creative" data-kind="story" class="creation-path"><span class="path-graphic path-idea">${icon('spark')}</span><div><small>01 / 从想法出发</small><strong>我有一句故事</strong><p>先记住这个念头，再一步步把画面搭起来。</p></div><span class="path-arrow">${icon('arrow')}</span></button><button data-action="templates" class="creation-path"><span class="path-graphic path-story">${icon('board')}</span><div><small>02 / 从画面出发</small><strong>我想先看看模板</strong><p>从一套可编辑的故事开始，改出自己的版本。</p></div><span class="path-arrow">${icon('arrow')}</span></button><button data-action="new-creative" data-kind="commerce" class="creation-path"><span class="path-graphic path-product">${icon('layers')}</span><div><small>03 / 从商品出发</small><strong>我想拍一支广告</strong><p>围绕真实卖点，设计商品画面和展示节奏。</p></div><span class="path-arrow">${icon('arrow')}</span></button></div></section>
 <section class="home-seeds"><div class="home-section-heading"><div><div class="home-eyebrow">A SPARK FOR YOUR STORY</div><h2>换一种情绪，故事就发生了。</h2></div>${button('templates','查看全部模板','arrow','text-btn')}</div><div class="seed-grid">${[
 ['lake','lake','一次回头，还没说出口。','日常爱情','暖调 · 克制表演 · 15秒'],
 ['mystery','night','门后的人，为什么不说话？','雨夜悬疑','冷暖对照 · 声音线索 · 15秒'],
 ['wuxia','wuxia','风起之前，先听见脚步。','古装武侠','云雾 · 衣摆 · 15秒']
 ].map(([id,theme,title,tag,note],i)=>`<button class="home-seed seed-${theme}" data-action="template-preview" data-id="${id}"><div class="seed-art"><img src="./assets/story-${id}.jpg" alt="${tag}原创氛围概念图" loading="lazy" width="1536" height="1024"><span class="seed-number">0${i+1}</span><span class="seed-image-label">AI氛围概念图</span><span class="seed-play">${icon('arrow')}</span></div><div class="seed-caption"><span>${tag}<small>内置故事模板</small></span><h3>${title}</h3><p>${note}</p></div></button>`).join('')}</div></section>
 <section class="future-gallery" aria-label="作品灵感馆，暂未开放"><div class="future-art" aria-hidden="true"><span></span><span></span><span></span></div><div><div class="home-eyebrow">THE INSPIRATION SCREENING ROOM</div><h2>下一场放映，留给好作品。</h2><p>作品灵感馆正在筹备。未来在这里，看成片、读分镜、发现新的创作方式。</p></div><span class="coming-soon">${icon('lock')}敬请期待 · 暂未开放</span></section></main><footer class="home-footer"><span>镜序 · 让每一秒，都有叙事。</span><div>${button('sources','方法与来源','','text-btn')}<span>你的内容，留在你的浏览器。</span></div></footer></div>`;
}
